// SPDX-License-Identifier: MIT
pragma solidity 0.8.9;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/GoldHunt.sol";

// Mock Uniswap sync interface
contract MockSync {
    function sync() external {
        // No-op implementation
    }
}

contract GoldHuntRebaseTest is Test {
    GoldHunt public token;
    MockSync public mockPair;

    address public owner = address(0xA);
    address public rewardsPool = address(0xB);

    uint256 public constant INITIAL_SUPPLY = 100_000_000 * 1e18;
    uint256 public constant TRANSFER_AMOUNT = 1_000 * 1e18;
    uint256 public constant REBASE_MULTIPLE = 2;

    function setUp() public {
        // Deploy contracts
        vm.startPrank(owner);
        token = new GoldHunt();
        mockPair = new MockSync();

        // Configure token
        token.setPair(address(mockPair));
        token.setRewardsPool(rewardsPool);

        // Prepare rewards pool
        token.transfer(rewardsPool, TRANSFER_AMOUNT);
        vm.stopPrank();
    }

    function test_rebaseOnlyByOwner() public {
        // Non-owner should not be able to rebase
        vm.expectRevert("Ownable: caller is not the owner");
        vm.prank(address(0xC));
        token.rebase(REBASE_MULTIPLE);
    }

    function test_rebaseInflation() public {
        // Record pre-rebase balances
        uint256 preTotalSupply = token.totalSupply();
        uint256 preRewardsBalance = token.balanceOf(rewardsPool);
        uint256 preOwnerBalance = token.balanceOf(owner);

        // Verify initial conditions
        assertEq(preTotalSupply, INITIAL_SUPPLY, "Initial total supply mismatch");
        assertEq(preRewardsBalance, TRANSFER_AMOUNT, "Initial rewards balance mismatch");
        assertEq(preOwnerBalance, INITIAL_SUPPLY - TRANSFER_AMOUNT, "Initial owner balance mismatch");

        // Perform rebase
        vm.prank(owner);
        token.rebase(REBASE_MULTIPLE);

        // Verify post-rebase state
        uint256 postRewardsBalance = token.balanceOf(rewardsPool);
        uint256 postOwnerBalance = token.balanceOf(owner);
        uint256 postTotalSupply = token.totalSupply();

        // Expected values after rebase(2)
        uint256 expectedTotalSupply = (INITIAL_SUPPLY + TRANSFER_AMOUNT) / 2; // Halved by new multiple
        uint256 expectedOwnerBalance = (INITIAL_SUPPLY - TRANSFER_AMOUNT) / 2; // Owner dilution

        // Assertions
        assertEq(postTotalSupply, expectedTotalSupply, "Inflation not properly applied");
        assertEq(postRewardsBalance, preRewardsBalance, "Rewards pool balance changed unexpectedly");
        assertEq(postOwnerBalance, expectedOwnerBalance, "Owner not properly diluted");
        assertLt(postOwnerBalance, preOwnerBalance, "Owner balance did not decrease");
    }
}
